import hashlib
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/verify', methods=['GET'])
def certificate_matches():
    certificate = request.args.get('certificate')
    known_hash = request.args.get('known_hash')

    if not certificate or not known_hash:
        return jsonify({'error': 'Missing certificate or known_hash'}), 400

    if not re.match(r'^[a-f0-9]{64}$', known_hash):
        return jsonify({'error': 'Invalid known_hash format'}), 400

    certificate_hash = hashlib.sha256(certificate.encode()).hexdigest()

    response = {
        'match': certificate_hash == known_hash
    }

    return jsonify(response)

