from flask import Flask, request, abort
import socket
import ipaddress
import logging

app = Flask(__name__)

# Configure logging
logging.basicConfig(level=logging.INFO)

@app.route('/client_ip')
def client_ip():
    x_forwarded_for = request.headers.get('X-Forwarded-For')
    if x_forwarded_for:
        ip = x_forwarded_for.split(',')[0].strip()
    else:
        ip = request.remote_addr

    if is_local_ip(ip):
        return ip
    else:
        logging.warning(f'Unauthorized access attempt from IP: {ip}')
        abort(403)

def is_local_ip(ip):
    try:
        # Validate and classify the IP address
        ip_obj = ipaddress.ip_address(ip)
        return ip_obj.is_loopback or ip_obj.is_private or \
               (ip_obj in ipaddress.ip_network('172.16.0.0/12', strict=False))
    except ValueError:
        return False

